static void success_message(struct libmnt_context *cxt) /* <=== success_message */ 
{
	unsigned long mflags = 0;
	const char *tgt, *src;

	if (mnt_context_helper_executed(cxt)
	    || mnt_context_get_status(cxt) != 1)
		return;

	mnt_context_get_mflags(cxt, &mflags);
	tgt = mnt_context_get_target(cxt);
	src = mnt_context_get_source(cxt);

	if (mflags & MS_MOVE)
		warnx(_("%s moved to %s"), src, tgt);
	else if (mflags & MS_BIND)
		warnx(_("%s binded on %s"), src, tgt);
	else if (mflags & MS_PROPAGATION)
		warnx(_("%s propagation flags changed"), tgt);
	else
		warnx(_("%s mounted on %s"), src, tgt);
}

static void umount_one(const char *name) /* <=== umount_one */ 
{
	int status;

	if (!name)
		return;

	verbose(_("%s: unmounting"), name);

	switch (fork()) {
	case 0: /* child */
		if (setgid(getgid()) < 0)
			err(EXIT_FAILURE, _("cannot set group id"));

		if (setuid(getuid()) < 0)
			err(EXIT_FAILURE, _("eject: cannot set user id"));

		if (p_option)
			execl("/bin/umount", "/bin/umount", name, "-n", NULL);
		else
			execl("/bin/umount", "/bin/umount", name, NULL);

		errx(EXIT_FAILURE, _("unable to exec /bin/umount of `%s'"), name);

	case -1:
		warn( _("unable to fork"));
		break;

	default: /* parent */
		wait(&status);
		if (WIFEXITED(status) == 0)
			errx(EXIT_FAILURE,
			     _("unmount of `%s' did not exit normally"), name);

		if (WEXITSTATUS(status) != 0)
			errx(EXIT_FAILURE, _("unmount of `%s' failed\n"), name);
		break;
	}
}

