	if (lc->fd < 0) {
		lc->mode = lc->flags & LOOPDEV_FL_RDWR ? O_RDWR : O_RDONLY;
		lc->fd = open(lc->device, lc->mode);
		DBG(lc, loopdev_debug("open %s [%s]: %s", lc->device,
				lc->flags & LOOPDEV_FL_RDWR ? "rw" : "ro",
				lc->fd < 0 ? "failed" : "ok"));
